//! Measurement-only probe: intentionally uncommitted and outside production code.
use crate::ssa::unit_lower::constant::lower_constant_unit_with_entry;
use lang_frontend::{
    lexer::lex,
    name_resolution::{SourceUnitInput, index_compilation_unit, resolve_compilation_unit_names},
    ownership_checking::check_compilation_unit_constant_ownership,
    parser::parse_file,
    source::SourceMap,
    type_checking::{check_compilation_unit_types, standard_environments},
};
use std::{env, fs, hint::black_box, path::PathBuf, time::Instant};

#[test]
fn const_index_probe() {
    let fixture = PathBuf::from(env::var_os("P3A_FIXTURE").expect("explicit fixture"));
    let mode = env::var("P3A_MODE").expect("explicit mode");
    assert!(matches!(mode.as_str(), "setup" | "index" | "lower" | "emit" | "factory" | "viewlower" | "viewemit"));
    let start = Instant::now();
    let manifest = fs::read_to_string(fixture.join("manifest.txt")).expect("fixture manifest");
    let paths: Vec<_> = manifest.lines().collect();
    let mut sources = SourceMap::new();
    let mut parsed = Vec::new();
    for path in &paths {
        let text = fs::read_to_string(fixture.join(path)).expect("fixture file");
        let source = sources.add_source(*path, text).expect("source");
        let tokens = lex(&sources, source).expect("lex");
        let file = parse_file(&sources, &tokens).expect("parse");
        assert!(file.diagnostics().is_empty(), "{:?}", file.diagnostics());
        parsed.push((source, file));
    }
    let inputs: Vec<_> = paths
        .iter()
        .zip(&parsed)
        .map(|(path, (source, file))| SourceUnitInput::new("root", *path, *source, file))
        .collect();
    let (name_environment, environment) = standard_environments();
    let index = index_compilation_unit(&sources, &inputs).expect("valid unit");
    let names = resolve_compilation_unit_names(&sources, &inputs, &index, &name_environment)
        .expect("names")
        .validate()
        .expect("validated names");
    let typed = check_compilation_unit_types(&sources, &inputs, &names, &environment)
        .expect("types")
        .validate_constants()
        .expect("validated types");
    let owned = check_compilation_unit_constant_ownership(&sources, &inputs, &names, &environment, &typed)
        .expect("ownership")
        .validate()
        .expect("validated ownership");
    let mut entries = names
        .names()
        .index()
        .declarations()
        .iter()
        .filter(|d| d.name() == "entry");
    let entry = entries.next().expect("entry").id();
    assert!(entries.next().is_none(), "unique entry");
    let setup_ns = start.elapsed().as_nanos();
    let operation = Instant::now();
    match mode.as_str() {
        "setup" => {}
        "index" => {
            black_box(index_compilation_unit(&sources, &inputs).expect("calibration index"));
        }
        "lower" => {
            black_box(
                lower_constant_unit_with_entry(
                    &sources,
                    &inputs,
                    &names,
                    &environment,
                    &typed,
                    &owned,
                    entry,
                )
                .expect("legacy lower"),
            );
        }
        "emit" => {
            let output = PathBuf::from(env::var_os("P3A_OUTPUT").expect("explicit output"));
            crate::emit_native_constant_unit_object(&sources, &inputs, &names, &environment,
                &typed, &owned, entry, &output).expect("legacy emit");
        }
        "factory" | "viewlower" | "viewemit" => {
            let unit = lang_frontend::ownership_checking::const_owned_compilation_unit_view(
                &sources, &inputs, &names, &environment, &typed, &owned).expect("factory");
            if mode == "viewlower" {
                black_box(crate::ssa::unit_lower::constant::lower_const_owned_unit_with_entry(
                    &unit, entry).expect("view lower"));
            } else if mode == "viewemit" {
                let output = PathBuf::from(env::var_os("P3A_OUTPUT").expect("explicit output"));
                crate::emit_native_const_owned_unit_object(&unit, entry, &output).expect("view emit");
            }
            black_box(unit);
        }
        _ => unreachable!(),
    }
    let operation_ns = operation.elapsed().as_nanos();
    black_box((
        &sources,
        &inputs,
        &names,
        &environment,
        &typed,
        &owned,
        &index,
    ));
    println!(
        "P3A_METRIC mode={mode} files={} setup_ns={setup_ns} operation_ns={operation_ns}",
        inputs.len()
    );
}

