from pathlib import Path
import json,hashlib,sys
A=Path(__file__).resolve().parent
exact={'index_entry':('lang_frontend::name_resolution::compilation_unit::index::index_compilation_unit','index.rs'), 'index_constructor':('<lang_frontend::name_resolution::compilation_unit::model::CompilationUnitIndex>::new','model.rs')}
def nm(p): return [v for l in p.read_text().splitlines() if len(v:=l.rsplit(' ',3))==4]
result={}
for cohort in sys.argv[1:]:
 raw=nm(A/f'{cohort}-mangled.txt'); dem=nm(A/f'{cohort}-demangled.txt'); selected={}
 for label,(name,file) in exact.items():
  ds=[r for r in dem if r[0]==name]; assert len(ds)==1,(label,ds)
  rs=[r for r in raw if r[1:]==ds[0][1:]]; assert len(rs)==1,(label,rs)
  selected[label]={'demangled':name,'mangled':rs[0][0],'type':rs[0][1],'address':rs[0][2],'size':rs[0][3],'source_file':file}
 fixtures={}; modes=['setup','index','lower','emit']+(['factory','viewlower','viewemit'] if cohort=='after' else [])
 for fixture in ['small','representative']:
  counts={}
  for mode in modes:
   data=json.loads((A/'profiles'/f'{cohort}-{fixture}-{mode}.json').read_text()); fs=[f for d in data['data'] for f in d['functions']]; counts[mode]={}
   for label,ident in selected.items():
    matches=[f for f in fs if f['name']==ident['mangled']]; assert len(matches)==1
    f=matches[0]; region=f['regions'][0]
    assert f['filenames'][region[5]].endswith('/name_resolution/compilation_unit/'+ident['source_file'])
    assert region[4]==f['count'];ident.setdefault('entry_region',region[:4]); counts[mode][label]=f['count']
   assert len(set(counts[mode].values()))==1
   out=(A/'profiles'/f'{cohort}-{fixture}-{mode}.stdout').read_text();assert '1 passed; 0 failed; 0 ignored;' in out
  delta={m:{k:counts[m][k]-counts['factory' if m.startswith('view') else 'setup'][k] for k in selected} for m in modes if m!='setup'}
  assert set(delta['index'].values())=={1}
  fixtures[fixture]={'counts':counts,'delta':delta}
 result[cohort]={'symbols':selected,'fixtures':fixtures,'binary_sha256':hashlib.sha256((A/'bin'/cohort).read_bytes()).hexdigest()}
result['fixtures']={d.name:[{'path':p,'sha256':hashlib.sha256((d/p).read_bytes()).hexdigest(),'bytes':(d/p).stat().st_size} for p in (d/'manifest.txt').read_text().splitlines()] for d in (A/'fixtures').iterdir()}
(A/'index-counts.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({c:{f:x['delta'] for f,x in v['fixtures'].items()} for c,v in result.items() if c!='fixtures'},indent=2))
